function findDuplicates(arr) {
    const dups = [];
    for (let i = 0; i < arr.length; i++) {
        for (let j = i+1; j < arr.length; j++) {
            if (arr[i] === arr[j] && !dups.includes(arr[i])) dups.push(arr[i]);
        }
    }
    return dups;
}
